// AscendC kernel for MoE Compute Expert Tokens
// Phase 1 (multi-core): partial histogram per core → workspace
// Phase 2 (single-core): reduction + inclusive prefix sum → output

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

__aicore__ inline int32_t CeilDiv(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<int32_t> &dst,
    AscendC::GlobalTensor<int32_t> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<int32_t> padParams{true, 0, 0, static_cast<int32_t>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<int32_t> dst,
    AscendC::LocalTensor<int32_t> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Phase 1: Multi-core partial histogram kernel
// =========================================================================

class MoeHistogramKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR sorted_expert,
        GM_ADDR workspace,
        int32_t totalLength,
        int32_t numExpert,
        int32_t tileLength,
        int32_t numCores)
    {
        totalLength_ = totalLength;
        numExpert_ = numExpert;
        tileLength_ = tileLength;
        numCores_ = numCores;

        sortedExpertGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(sorted_expert),
            static_cast<uint64_t>(totalLength));
        workspaceGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(workspace),
            static_cast<uint64_t>(numCores) * static_cast<uint64_t>(numExpert));

        if ASCEND_IS_AIV {
            // UB buffers
            // src_ub: input tile (loaded once, reused for all expert comparisons)
            // cmp_ub: comparison result (0xFFFFFFFF for match, 0 for no-match)
            // red_tmp: reduce temporary (2x tileLength uint8_t)
            // local_hist: partial histogram accumulator (numExpert int32_t)
            pipe_.InitBuffer(srcBuf_, tileLength_ * sizeof(int32_t));
            pipe_.InitBuffer(cmpBuf_, tileLength_ * sizeof(int32_t));
            pipe_.InitBuffer(redTmpBuf_, 2 * tileLength_ * sizeof(uint8_t));
            pipe_.InitBuffer(histBuf_, numExpert_ * sizeof(int32_t));

            srcLocal_ = srcBuf_.Get<int32_t>();
            cmpLocal_ = cmpBuf_.Get<int32_t>();
            redTmpLocal_ = redTmpBuf_.Get<uint8_t>();
            histLocal_ = histBuf_.Get<int32_t>();

            // Initialize histogram to zero
            AscendC::Duplicate<int32_t>(histLocal_, static_cast<int32_t>(0), numExpert_);
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx();
            int32_t perCoreLen = CeilDiv(totalLength_, numCores_);
            int32_t coreStart = coreIdx * perCoreLen;
            int32_t coreEnd = coreStart + perCoreLen;
            if (coreEnd > totalLength_) { coreEnd = totalLength_; }
            int32_t coreLen = coreEnd - coreStart;

            if (coreLen <= 0) { return; }

            int32_t numTiles = CeilDiv(coreLen, tileLength_);

            for (int32_t t = 0; t < numTiles; ++t) {
                int32_t tileStart = coreStart + t * tileLength_;
                int32_t tileEnd = tileStart + tileLength_;
                if (tileEnd > coreEnd) { tileEnd = coreEnd; }
                int32_t curLen = tileEnd - tileStart;

                CopyIn(tileStart, curLen);
                Compute(curLen);
            }

            CopyOutHist(coreIdx);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t offset, int32_t curLen)
    {
        // Load input tile into src_ub via DataCopyPad
        LoadGmToUb(srcLocal_, sortedExpertGM_[offset], static_cast<uint32_t>(curLen));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
    }

    __aicore__ inline void Compute(int32_t curLen)
    {
        // For each expert e, compare tile elements == e, count matches
        for (int32_t e = 0; e < numExpert_; ++e) {
            // Compare: matching elements get 0xFFFFFFFF (-1 as int32)
            AscendC::Compare(cmpLocal_, srcLocal_, static_cast<int32_t>(e),
                             AscendC::CMPMODE::EQ, curLen);
            AscendC::PipeBarrier<PIPE_V>();

            // ReduceSum: sum of -1s = -count
            // We use a scalar sum buffer approach
            AscendC::ReduceSum<int32_t>(sumLocal_, cmpLocal_, redTmpLocal_, curLen);
            AscendC::PipeBarrier<PIPE_V>();

            // Get the negative sum and convert to positive count
            int32_t negSum = sumLocal_.GetValue(0);
            int32_t count = -negSum;  // -(-count) = count

            if (count > 0) {
                int32_t oldVal = histLocal_.GetValue(e);
                AscendC::Duplicate<int32_t>(histLocal_, static_cast<int32_t>(oldVal + count), numExpert_);
                // Restore other elements (Duplicate sets ALL elements)
                // Actually, Duplicate sets the entire buffer to the same value.
                // Need a different approach for element-wise update.
            }
        }
    }

    __aicore__ inline void CopyOutHist(int32_t coreIdx)
    {
        int32_t wsOffset = coreIdx * numExpert_;
        StoreUbToGm(workspaceGM_[wsOffset], histLocal_, static_cast<uint32_t>(numExpert_));
        AscendC::PipeBarrier<PIPE_MTE2>();
    }

private:
    int32_t totalLength_ = 0;
    int32_t numExpert_ = 0;
    int32_t tileLength_ = 0;
    int32_t numCores_ = 0;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<int32_t> sortedExpertGM_;
    AscendC::GlobalTensor<int32_t> workspaceGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> srcBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> redTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;

    AscendC::LocalTensor<int32_t> srcLocal_;
    AscendC::LocalTensor<int32_t> cmpLocal_;
    AscendC::LocalTensor<uint8_t> redTmpLocal_;
    AscendC::LocalTensor<int32_t> histLocal_;
    AscendC::LocalTensor<int32_t> sumLocal_;  // scalar result from ReduceSum
};

__aicore__ inline void KernelMoeHistogramProcess(
    GM_ADDR sorted_expert, GM_ADDR workspace,
    int32_t totalLength, int32_t numExpert,
    int32_t tileLength, int32_t numCores)
{
    MoeHistogramKernel kernel;
    kernel.Init(sorted_expert, workspace, totalLength, numExpert, tileLength, numCores);
    kernel.Process();
}

// =========================================================================
// Phase 2: Single-core reduction + inclusive prefix sum kernel
// =========================================================================

class MoeReduceKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR workspace,
        GM_ADDR expert_tokens,
        int32_t numExpert,
        int32_t numCores)
    {
        numExpert_ = numExpert;
        numCores_ = numCores;

        workspaceGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(workspace),
            static_cast<uint64_t>(numCores) * static_cast<uint64_t>(numExpert));
        outputGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(expert_tokens),
            static_cast<uint64_t>(numExpert));

        if ASCEND_IS_AIV {
            // UB buffers for reduction
            pipe_.InitBuffer(partialBuf_, numExpert_ * sizeof(int32_t));
            pipe_.InitBuffer(accumBuf_, numExpert_ * sizeof(int32_t));

            partialLocal_ = partialBuf_.Get<int32_t>();
            accumLocal_ = accumBuf_.Get<int32_t>();

            // Initialize accumulator to zero
            AscendC::Duplicate<int32_t>(accumLocal_, static_cast<int32_t>(0), numExpert_);
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            // Step 1: Sum all partial histograms from workspace
            for (int32_t c = 0; c < numCores_; ++c) {
                int32_t wsOffset = c * numExpert_;
                CopyInPartial(wsOffset);
                Accumulate();
            }

            // Step 2: Inclusive prefix sum on accumulator
            PrefixSum();

            // Step 3: Write output
            CopyOut();
        }
    }

private:
    __aicore__ inline void CopyInPartial(int32_t wsOffset)
    {
        LoadGmToUb(partialLocal_, workspaceGM_[wsOffset], static_cast<uint32_t>(numExpert_));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
    }

    __aicore__ inline void Accumulate()
    {
        AscendC::Add(accumLocal_, accumLocal_, partialLocal_, numExpert_);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void PrefixSum()
    {
        // Inclusive prefix sum: output[i] = accum[0] + accum[1] + ... + accum[i]
        // Since numExpert is small, use scalar accumulation
        int32_t running = 0;
        for (int32_t i = 0; i < numExpert_; ++i) {
            running += accumLocal_.GetValue(i);
            AscendC::Duplicate<int32_t>(accumLocal_, static_cast<int32_t>(running), numExpert_);
            // Problem: Duplicate sets ALL elements to the same value.
            // Need a different approach for prefix sum.
        }
    }

    __aicore__ inline void CopyOut()
    {
        StoreUbToGm(outputGM_[0], accumLocal_, static_cast<uint32_t>(numExpert_));
        AscendC::PipeBarrier<PIPE_MTE2>();
    }

private:
    int32_t numExpert_ = 0;
    int32_t numCores_ = 0;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<int32_t> workspaceGM_;
    AscendC::GlobalTensor<int32_t> outputGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> partialBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accumBuf_;

    AscendC::LocalTensor<int32_t> partialLocal_;
    AscendC::LocalTensor<int32_t> accumLocal_;
};

__aicore__ inline void KernelMoeReduceProcess(
