// MoE Compute Expert Tokens op_host
// Tiling calculation + two-phase kernel launch (histogram → reduce)

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_moe_compute_expert_tokens_histogram.h"
#include "aclrtlaunch_moe_compute_expert_tokens_reduce.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_TILE_LENGTH = 2048;  // int32 elements per UB tile
constexpr int32_t MAX_CORES = 40;               // max active AI Cores

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor moe_compute_expert_tokens(
    const at::Tensor &sorted_expert_for_source_row,
    int64_t num_expert)
{
    // Input validation
    TORCH_CHECK(sorted_expert_for_source_row.dim() == 1,
                "sorted_expert_for_source_row must be 1D");
    TORCH_CHECK(sorted_expert_for_source_row.scalar_type() == at::kInt,
                "sorted_expert_for_source_row must be int32");
    TORCH_CHECK(num_expert > 0, "num_expert must be positive");
    TORCH_CHECK(sorted_expert_for_source_row.is_contiguous(),
                "sorted_expert_for_source_row must be contiguous");

    int32_t N = static_cast<int32_t>(sorted_expert_for_source_row.sizes()[0]);
    int32_t numExpert = static_cast<int32_t>(num_expert);

    // Determine number of cores and tile length
    int32_t numCores = std::min<int32_t>(MAX_CORES, std::max<int32_t>(1, (N + DEFAULT_TILE_LENGTH - 1) / DEFAULT_TILE_LENGTH));
    int32_t tileLength = DEFAULT_TILE_LENGTH;

    // Create output tensor: [num_expert] int32
    at::Tensor output = at::empty({numExpert}, sorted_expert_for_source_row.options());

    // Create workspace tensor: [numCores * numExpert] int32
    // Holds partial histograms from each core
    at::Tensor workspace = at::empty({numCores, numExpert}, sorted_expert_for_source_row.options());

    // Ensure workspace is contiguous
    workspace = workspace.contiguous();

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    uint32_t histBlockDim = static_cast<uint32_t>(numCores);
    uint32_t reduceBlockDim = static_cast<uint32_t>(1);  // single core for reduction

    // Phase 1: Multi-core histogram
    EXEC_KERNEL_CMD(moe_compute_expert_tokens_histogram, histBlockDim,
                    sorted_expert_for_source_row, workspace,
                    N, numExpert, tileLength, numCores);

    // Phase 2: Single-core reduction + prefix sum
    EXEC_KERNEL_CMD(moe_compute_expert_tokens_reduce, reduceBlockDim,
                    workspace, output,
                    numExpert, numCores);

    return output;
}

}  // namespace ascend_kernel
